+			...(this.hiddenForChat ? { hiddenForChat: true } : {}),
+			seq: this.seq,
+			...(this.lastPush ? { lastPush: this.lastPush } : {}),
+			...(this.lastTurn ? { lastTurn: this.lastTurn } : {}),
+			...(this.lastChat ? { lastChat: this.lastChat } : {}),
